const verificationLoopbackHosts = new Set(["localhost", "127.0.0.1", "::1"]);
function authAttemptLimit(): number {
  if (process.env.NODE_ENV !== "test" || process.env.ERP_VERIFY_ALLOW_MUTATION !== "1") return 10;
  try {
    const url = new URL(process.env.DATABASE_URL ?? "");
    const databaseName = decodeURIComponent(url.pathname.replace(/^\/+/, ""));
    if ((url.protocol === "postgres:" || url.protocol === "postgresql:")
        && verificationLoopbackHosts.has(url.hostname)
        && databaseName !== ""
        && databaseName === process.env.ERP_VERIFY_EXPECTED_DATABASE) return 100;
  } catch {
    // An invalid or non-disposable verification target keeps the production-safe limit.
  }
  return 10;
}
const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, limit: authAttemptLimit(), standardHeaders: true, legacyHeaders: false });
