  const locked=await client.query("SELECT id FROM products WHERE company_id=$1 AND id=ANY($2::uuid[]) ORDER BY id FOR UPDATE",[cid,products]);
  if(locked.rowCount!==products.length)throw Object.assign(new Error("One or more products were not found in this company."),{httpStatus:404,errorCode:"PRODUCT_NOT_FOUND"});
  const location=await client.query<{branch_id:string|null;name:string}>("SELECT branch_id,name FROM stock_locations WHERE company_id=$1 AND id=$2 AND active=true AND ($3::uuid IS NULL OR branch_id IS NULL OR branch_id=$3) FOR UPDATE",[cid,x.locationId,req.auth!.branchId]);
  if(!location.rowCount)throw Object.assign(new Error("Choose an active stock location in your current branch."),{httpStatus:404,errorCode:"LOCATION_NOT_FOUND"});
  const dateResult=await client.query<{today:string}>("SELECT timezone(c.timezone,now())::date::text AS today FROM companies c WHERE c.id=$1",[cid]);
  const effectiveDate=dateResult.rows[0].today,number=await nextDocumentNumber(client,cid,"inventory_valuation_reconciliation");
