app.get("/api/stocktakes",requireAuth,requirePermission("stock.view"),async(req,res,next)=>{try{const q=await pool.query(`SELECT s.id,s.stocktake_number AS \"stocktakeNumber\",s.status,s.notes,s.created_at AS \"createdAt\",s.submitted_at AS \"submittedAt\",s.approved_at AS \"approvedAt\",l.name AS \"locationName\",u.full_name AS \"createdBy\",count(sl.id)::int AS \"lineCount\",count(sl.id) FILTER(WHERE sl.counted_quantity IS NOT NULL)::int AS \"countedLines\" FROM stocktakes s JOIN stock_locations l ON l.company_id=s.company_id AND l.id=s.location_id JOIN users u ON u.company_id=s.company_id AND u.id=s.created_by LEFT JOIN stocktake_lines sl ON sl.company_id=s.company_id AND sl.stocktake_id=s.id WHERE s.company_id=$1 AND ($2::uuid IS NULL OR l.branch_id IS NULL OR l.branch_id=$2) GROUP BY s.id,l.name,u.full_name ORDER BY s.created_at DESC LIMIT 100`,[req.auth!.companyId,req.auth!.branchId]);return res.json({stocktakes:q.rows});}catch(e){return next(e);}});
app.get("/api/stocktakes/:id",requireAuth,requirePermission("stock.view"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id);if(!id.success)return res.status(404).json({error:{code:"STOCKTAKE_NOT_FOUND",message:"Stock count was not found."}});try{const q=await pool.query(`SELECT s.id,s.stocktake_number AS \"stocktakeNumber\",s.status,s.notes,l.name AS \"locationName\" FROM stocktakes s JOIN stock_locations l ON l.company_id=s.company_id AND l.id=s.location_id WHERE s.company_id=$1 AND s.id=$2 AND ($3::uuid IS NULL OR l.branch_id IS NULL OR l.branch_id=$3)`,[req.auth!.companyId,id.data,req.auth!.branchId]);if(!q.rowCount)return res.status(404).json({error:{code:"STOCKTAKE_NOT_FOUND",message:"Stock count was not found."}});const lines=await pool.query(`SELECT sl.id AS \"lineId\",sl.product_id AS \"productId\",p.name AS \"productName\",p.code,p.unit,sl.quality,sl.expected_quantity AS \"expectedQuantity\",sl.counted_quantity AS \"countedQuantity\",sl.entered_counted_quantity AS \"enteredCountedQuantity\",sl.counted_unit_code AS \"countedUnitCode\",sl.counted_conversion_to_base AS \"countedConversionToBase\" FROM stocktake_lines sl JOIN products p ON p.company_id=sl.company_id AND p.id=sl.product_id WHERE sl.company_id=$1 AND sl.stocktake_id=$2 ORDER BY lower(p.name),sl.quality`,[req.auth!.companyId,id.data]);return res.json({stocktake:q.rows[0],lines:lines.rows});}catch(e){return next(e);}});
