app.get("/api/brokers/:id/ledger",requireAuth,requirePermission("brokers.commission.view"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id);if(!id.success)return res.status(404).json({error:{code:"BROKER_NOT_FOUND",message:"Broker was not found."}});try{const q=await pool.query(`SELECT je.entry_number AS \"entryNumber\",je.effective_date AS \"postedAt\",je.description,jl.description AS detail,jl.debit,jl.credit,SUM(jl.credit-jl.debit) OVER(ORDER BY je.effective_date,je.entry_number,jl.line_number ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS balance FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id JOIN business_partners b ON b.company_id=jl.company_id AND b.id=jl.broker_id WHERE jl.company_id=$1 AND jl.broker_id=$2 AND b.partner_type='broker' AND a.code='2150' AND ($3::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$3) ORDER BY je.effective_date,je.entry_number,jl.line_number`,[req.auth!.companyId,id.data,req.auth!.branchId]);return res.json({entries:q.rows,balance:q.rows.at(-1)?.balance??0});}catch(e){return next(e);}});
