app.get("/api/sales/invoices/:id/returnable-lines",requireAuth,requirePermission("sales.view"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id);if(!id.success)return res.status(404).json({error:{code:"INVOICE_NOT_FOUND",message:"Invoice was not found."}});try{const invoice=await pool.query("SELECT id,invoice_number AS \"invoiceNumber\",customer_id AS \"customerId\",invoice_date AS \"invoiceDate\",status FROM sales_invoices WHERE company_id=$1 AND id=$2 AND ($3::uuid IS NULL OR branch_id IS NULL OR branch_id=$3)",[req.auth!.companyId,id.data,req.auth!.branchId]);if(!invoice.rowCount)return res.status(404).json({error:{code:"INVOICE_NOT_FOUND",message:"Invoice was not found."}});const lines=await pool.query(`SELECT l.id AS \"invoiceLineId\",l.product_id AS \"productId\",p.name AS \"productName\",p.code,l.quality,l.quantity AS \"invoicedQuantity\",l.quantity-COALESCE((SELECT SUM(rl.quantity) FROM sales_return_lines rl WHERE rl.company_id=l.company_id AND rl.invoice_line_id=l.id),0) AS \"returnableQuantity\",l.unit_rate AS \"unitRate\",l.tax_rate AS \"taxRate\" FROM sales_invoice_lines l JOIN products p ON p.company_id=l.company_id AND p.id=l.product_id WHERE l.company_id=$1 AND l.invoice_id=$2 AND l.quantity>COALESCE((SELECT SUM(rl.quantity) FROM sales_return_lines rl WHERE rl.company_id=l.company_id AND rl.invoice_line_id=l.id),0) ORDER BY l.line_number`,[req.auth!.companyId,id.data]);return res.json({invoice:invoice.rows[0],lines:lines.rows});}catch(e){return next(e);}});

const salesReturnSchema=z.object({returnDate:z.string().date(),reason:z.string().trim().min(5).max(500),lines:z.array(z.object({invoiceLineId:z.string().uuid(),quantity:z.coerce.number().positive().max(10000000),restockQuality:z.enum(["good","second","damaged"])})).min(1).max(100)}).superRefine((v,ctx)=>{if(new Set(v.lines.map(l=>l.invoiceLineId)).size!==v.lines.length)ctx.addIssue({code:"custom",message:"A sale line may be included only once per return.",path:["lines"]});});
