app.post("/api/employees/:id/opening-balance",requireAuth,requirePermission("employees.opening.post"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id),p=employeeOpeningSchema.safeParse(req.body);if(!id.success)return res.status(404).json({error:{code:"EMPLOYEE_NOT_FOUND",message:"Employee was not found."}});if(!p.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Enter a positive opening advance, date and reason of at least five characters."}});const x=p.data,cid=req.auth!.companyId,actor=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation="employees.opening_balance:"+id.data,client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,body:{employeeId:id.data,...x}});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}const employee=await client.query<{id:string;full_name:string}>("SELECT id,full_name FROM employees WHERE company_id=$1 AND id=$2 FOR UPDATE",[cid,id.data]);if(!employee.rowCount)throw Object.assign(new Error("Employee was not found."),{httpStatus:404,errorCode:"EMPLOYEE_NOT_FOUND"});const existing=await client.query("SELECT id FROM employee_opening_balances WHERE company_id=$1 AND employee_id=$2",[cid,id.data]);if(existing.rowCount)throw Object.assign(new Error("An opening balance has already been posted for this employee."),{httpStatus:409,errorCode:"OPENING_ALREADY_POSTED"});const activity=await client.query("SELECT id FROM journal_entry_lines WHERE company_id=$1 AND employee_id=$2 LIMIT 1",[cid,id.data]);if(activity.rowCount)throw Object.assign(new Error("Opening balance must be posted before advances, repayments or salary transactions."),{httpStatus:409,errorCode:"EMPLOYEE_LEDGER_ALREADY_STARTED"});const amount=cents(x.amount),number=await nextDocumentNumber(client,cid,"employee_opening_balance"),opening=await client.query<{id:string}>("INSERT INTO employee_opening_balances(company_id,employee_id,opening_number,opening_date,amount,reason,created_by) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id",[cid,id.data,number,x.openingDate,amount,x.reason,actor]);await writeJournal(client,{companyId:cid,actorId:actor,sourceType:"employee_opening_balance",sourceId:opening.rows[0].id,description:`Employee opening balance ${number}: ${employee.rows[0].full_name}`,effectiveDate:x.openingDate,branchId:req.auth!.branchId,lines:[{accountCode:"1400",employeeId:id.data,description:`Opening employee advance ${number}`,debit:amount,credit:0},{accountCode:"3000",description:`Opening employee advance equity ${number}`,debit:0,credit:amount}]});await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'employee.opening.post','employee_opening_balance',$3,$4,$5::jsonb)",[cid,actor,opening.rows[0].id,x.reason,JSON.stringify({...x,employeeId:id.data,amount,openingNumber:number})]);const response={id:opening.rows[0].id,openingNumber:number,amount};await completeIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,status:201,body:response});await client.query("COMMIT");return res.status(201).json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"EMPLOYEE_OPENING_INVALID",message:(e as Error).message}});if((e as {code?:string}).code==="23505")return res.status(409).json({error:{code:"OPENING_ALREADY_POSTED",message:"An opening balance has already been posted for this employee."}});return next(e);}finally{client.release();}});
const employeeLedgerFilterSchema=z.object({from:z.string().date().optional(),to:z.string().date().optional()});
app.get("/api/employees/:id/ledger",requireAuth,requirePermission("employees.view"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id),f=employeeLedgerFilterSchema.safeParse(req.query);if(!id.success)return res.status(404).json({error:{code:"EMPLOYEE_NOT_FOUND",message:"Employee was not found."}});if(!f.success||(f.data.from&&f.data.to&&f.data.from>f.data.to))return res.status(400).json({error:{code:"INVALID_LEDGER_FILTER",message:"Choose a valid employee-ledger date range."}});try{const employee=await pool.query(`SELECT id,employee_number AS "employeeNumber",full_name AS "fullName",job_title AS "jobTitle",employment_type AS "employmentType",active FROM employees WHERE company_id=$1 AND id=$2 AND ($3::uuid IS NULL OR branch_id=$3)`,[req.auth!.companyId,id.data,req.auth!.branchId]);if(!employee.rowCount)return res.status(404).json({error:{code:"EMPLOYEE_NOT_FOUND",message:"Employee was not found."}});const params=[req.auth!.companyId,id.data,f.data.from??null,f.data.to??null];const base=`FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE jl.company_id=$1 AND jl.employee_id=$2 AND ($4::date IS NULL OR je.effective_date<=$4::date)`;const [ledger,summary]=await Promise.all([pool.query(`WITH lines AS (SELECT je.id AS "journalEntryId",je.effective_date AS "effectiveDate",je.entry_number AS "entryNumber",je.created_at AS "createdAt",je.source_type AS "sourceType",je.source_id AS "sourceId",jl.line_number AS "lineNumber",jl.description,a.code AS "accountCode",a.name AS "accountName",jl.debit,jl.credit ${base}),balances AS (SELECT lines.*,SUM(debit-credit) OVER(PARTITION BY "accountCode" ORDER BY "effectiveDate","createdAt","entryNumber","lineNumber" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)::numeric(14,2) AS "runningBalance" FROM lines) SELECT balances.*,count(*) OVER()::int AS "totalLines" FROM balances WHERE ($3::date IS NULL OR "effectiveDate">=$3::date) ORDER BY "effectiveDate","createdAt","entryNumber","lineNumber" LIMIT 10000`,params),pool.query(`SELECT a.code AS "accountCode",a.name AS "accountName",COALESCE(SUM(jl.debit-jl.credit) FILTER(WHERE $3::date IS NOT NULL AND je.effective_date<$3::date),0)::numeric(14,2) AS "openingBalance",COALESCE(SUM(jl.debit) FILTER(WHERE $3::date IS NULL OR je.effective_date>=$3::date),0)::numeric(14,2) AS "periodDebits",COALESCE(SUM(jl.credit) FILTER(WHERE $3::date IS NULL OR je.effective_date>=$3::date),0)::numeric(14,2) AS "periodCredits",COALESCE(SUM(jl.debit-jl.credit),0)::numeric(14,2) AS "closingBalance" ${base} GROUP BY a.code,a.name ORDER BY a.code`,params)]);return res.json({employee:employee.rows[0],rows:ledger.rows,accounts:summary.rows,totalLines:Number(ledger.rows[0]?.totalLines??0),limit:10000,from:f.data.from??null,to:f.data.to??null});}catch(error){return next(error);}});app.get("/api/employees",requireAuth,requirePermission("employees.view"),async(req,res,next)=>{try{const q=await pool.query(`SELECT e.id,e.branch_id AS \"branchId\",b.name AS \"branchName\",e.employee_number AS \"employeeNumber\",e.full_name AS \"fullName\",e.phone,e.email,e.job_title AS \"jobTitle\",e.department,e.employment_type AS \"employmentType\",e.joined_on::text AS \"joinedOn\",e.base_daily_rate AS \"baseDailyRate\",e.active,COALESCE(SUM(CASE WHEN je.id IS NOT NULL THEN jl.debit-jl.credit ELSE 0 END),0) AS \"advanceBalance\",EXISTS(SELECT 1 FROM employee_opening_balances ob WHERE ob.company_id=e.company_id AND ob.employee_id=e.id) AS \"openingBalancePosted\",EXISTS(SELECT 1 FROM journal_entry_lines ledger WHERE ledger.company_id=e.company_id AND ledger.employee_id=e.id) AS \"hasLedgerActivity\" FROM employees e LEFT JOIN branches b ON b.company_id=e.company_id AND b.id=e.branch_id LEFT JOIN journal_entry_lines jl ON jl.company_id=e.company_id AND jl.employee_id=e.id LEFT JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id WHERE e.company_id=$1 AND ($2::uuid IS NULL OR e.branch_id=$2) GROUP BY e.id,b.name ORDER BY e.active DESC,lower(e.full_name)`,[req.auth!.companyId,req.auth!.branchId]);return res.json({employees:q.rows});}catch(e){return next(e);}});
