app.get("/api/accounting/trial-balance",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{const parsed=reportDates.extend({financialYearId:z.string().uuid().optional()}).safeParse(req.query);if(!parsed.success||(parsed.data.from&&parsed.data.to&&parsed.data.from>parsed.data.to))return res.status(400).json({error:{code:"INVALID_DATE_RANGE",message:"Check the report start and end dates."}});try{if(parsed.data.financialYearId){const selected=await pool.query("SELECT id FROM financial_years WHERE company_id=$1 AND id=$2",[req.auth!.companyId,parsed.data.financialYearId]);if(!selected.rowCount)return res.status(404).json({error:{code:"FINANCIAL_YEAR_NOT_FOUND",message:"Financial year was not found."}});}const q=await pool.query(`SELECT a.code,a.name,a.account_type AS \"accountType\",CASE WHEN $5::uuid IS NULL AND os.id IS NOT NULL THEN COALESCE(osl.opening_debit,0)+COALESCE(SUM(CASE WHEN je.id IS NOT NULL AND je.effective_date>=fy.starts_on AND je.source_type<>'financial_year_close' THEN jl.debit ELSE 0 END),0) ELSE COALESCE(SUM(CASE WHEN je.id IS NOT NULL AND (a.account_type NOT IN ('income','expense') OR ((COALESCE($3::date,fy.starts_on) IS NULL OR je.effective_date >= COALESCE($3::date,fy.starts_on)) AND je.source_type<>'financial_year_close')) THEN jl.debit ELSE 0 END),0) END AS debit,CASE WHEN $5::uuid IS NULL AND os.id IS NOT NULL THEN COALESCE(osl.opening_credit,0)+COALESCE(SUM(CASE WHEN je.id IS NOT NULL AND je.effective_date>=fy.starts_on AND je.source_type<>'financial_year_close' THEN jl.credit ELSE 0 END),0) ELSE COALESCE(SUM(CASE WHEN je.id IS NOT NULL AND (a.account_type NOT IN ('income','expense') OR ((COALESCE($3::date,fy.starts_on) IS NULL OR je.effective_date >= COALESCE($3::date,fy.starts_on)) AND je.source_type<>'financial_year_close')) THEN jl.credit ELSE 0 END),0) END AS credit FROM accounts a LEFT JOIN financial_years fy ON fy.company_id=a.company_id AND fy.id=$2 LEFT JOIN financial_year_opening_snapshots os ON os.company_id=fy.company_id AND os.financial_year_id=fy.id LEFT JOIN financial_year_opening_snapshot_lines osl ON osl.company_id=os.company_id AND osl.snapshot_id=os.id AND osl.account_id=a.id LEFT JOIN journal_entry_lines jl ON jl.company_id=a.company_id AND jl.account_id=a.id LEFT JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id AND ($4::date IS NULL OR je.effective_date <= $4::date) AND ($5::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$5) WHERE a.company_id=$1 AND a.active=true GROUP BY a.id,fy.starts_on,os.id,osl.opening_debit,osl.opening_credit ORDER BY a.code`,[req.auth!.companyId,parsed.data.financialYearId??null,parsed.data.from??null,parsed.data.to??null,req.auth!.branchId]);const rows=q.rows.map(r=>({...r,debit:Number(r.debit),credit:Number(r.credit),balance:Number(r.accountType==="asset"||r.accountType==="expense"?r.debit-r.credit:r.credit-r.debit)}));return res.json({rows,totalDebit:rows.reduce((s,r)=>s+r.debit,0),totalCredit:rows.reduce((s,r)=>s+r.credit,0),from:parsed.data.from??null,to:parsed.data.to??null,financialYearId:parsed.data.financialYearId??null});}catch(e){return next(e);}});
app.get("/api/accounting/profit-loss",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{const parsed=reportDates.safeParse(req.query);if(!parsed.success||(parsed.data.from&&parsed.data.to&&parsed.data.from>parsed.data.to))return res.status(400).json({error:{code:"INVALID_DATE_RANGE",message:"Check the report start and end dates."}});try{const q=await pool.query(`SELECT a.code,a.name,a.account_type AS \"accountType\",COALESCE(SUM(jl.debit),0) AS debit,COALESCE(SUM(jl.credit),0) AS credit FROM accounts a JOIN journal_entry_lines jl ON jl.company_id=a.company_id AND jl.account_id=a.id JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id WHERE a.company_id=$1 AND a.active=true AND a.account_type IN ('income','expense') AND je.source_type<>'financial_year_close' AND ($2::date IS NULL OR je.effective_date >= $2::date) AND ($3::date IS NULL OR je.effective_date <= $3::date) AND ($4::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$4) GROUP BY a.id ORDER BY a.account_type,a.code`,[req.auth!.companyId,parsed.data.from??null,parsed.data.to??null,req.auth!.branchId]);const rows=q.rows.map(r=>({...r,debit:Number(r.debit),credit:Number(r.credit),amount:Number(r.accountType==="income"?r.credit-r.debit:r.debit-r.credit)})),income=rows.filter(r=>r.accountType==="income").reduce((s,r)=>s+r.amount,0),expenses=rows.filter(r=>r.accountType==="expense").reduce((s,r)=>s+r.amount,0);return res.json({rows,income,expenses,netProfit:income-expenses,from:parsed.data.from??null,to:parsed.data.to??null});}catch(e){return next(e);}});
app.get("/api/accounting/balance-sheet",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{const parsed=reportDates.pick({to:true}).safeParse(req.query);if(!parsed.success)return res.status(400).json({error:{code:"INVALID_DATE_RANGE",message:"Choose a valid balance sheet date."}});try{const q=await pool.query(`SELECT a.code,a.name,a.account_type AS \"accountType\",COALESCE(SUM(CASE WHEN je.id IS NOT NULL THEN jl.debit ELSE 0 END),0) AS debit,COALESCE(SUM(CASE WHEN je.id IS NOT NULL THEN jl.credit ELSE 0 END),0) AS credit FROM accounts a LEFT JOIN journal_entry_lines jl ON jl.company_id=a.company_id AND jl.account_id=a.id LEFT JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id AND ($2::date IS NULL OR je.effective_date <= $2::date) AND ($3::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$3) WHERE a.company_id=$1 AND a.active=true GROUP BY a.id ORDER BY a.account_type,a.code`,[req.auth!.companyId,parsed.data.to??null,req.auth!.branchId]);const accounts=q.rows.map(r=>{const debit=Number(r.debit),credit=Number(r.credit);return{...r,debit,credit,balance:Number(r.accountType==="asset"||r.accountType==="expense"?debit-credit:credit-debit)}});const assets=accounts.filter(r=>r.accountType==="asset"&&Math.abs(r.balance)>=0.005),liabilities=accounts.filter(r=>r.accountType==="liability"&&Math.abs(r.balance)>=0.005),equity=accounts.filter(r=>r.accountType==="equity"&&Math.abs(r.balance)>=0.005),income=accounts.filter(r=>r.accountType==="income").reduce((s,r)=>s+r.balance,0),expenses=accounts.filter(r=>r.accountType==="expense").reduce((s,r)=>s+r.balance,0),currentEarnings=cents(income-expenses),totalAssets=cents(assets.reduce((s,r)=>s+r.balance,0)),totalLiabilities=cents(liabilities.reduce((s,r)=>s+r.balance,0)),totalEquity=cents(equity.reduce((s,r)=>s+r.balance,0)),totalLiabilitiesAndEquity=cents(totalLiabilities+totalEquity+currentEarnings);return res.json({assets,liabilities,equity,currentEarnings,totalAssets,totalLiabilities,totalEquity,totalLiabilitiesAndEquity,balanced:Math.abs(totalAssets-totalLiabilitiesAndEquity)<0.01,asOf:parsed.data.to??null});}catch(e){return next(e);}});
const loadingCreateSchema=z.object({invoiceId:z.string().uuid(),vehicleId:z.string().uuid(),driverId:z.string().uuid(),destination:z.string().trim().max(500).optional().default("")});
const loadingQuantitySchema=z.object({quantity:z.coerce.number().min(0).max(999999999)});
const loadingPhotoSchema=z.object({photoType:z.enum(["before","during","after"]),contentType:z.enum(["image/jpeg","image/png","image/webp"]),imageBase64:z.string().min(1).max(1000000)});
