app.post("/api/accounting/bank-reconciliations/:id/lines/:lineId/match",requireAuth,requirePermission("bank.reconcile.match"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id),lineId=z.string().uuid().safeParse(req.params.lineId),p=bankMatchSchema.safeParse(req.body);if(!id.success||!lineId.success)return res.status(404).json({error:{code:"BANK_RECONCILIATION_NOT_FOUND",message:"Bank reconciliation line was not found."}});if(!p.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Select a posted bank transaction to match."}});const cid=req.auth!.companyId,userId=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation=`accounting.bank_reconciliation.match:${id.data}:${lineId.data}`,client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:cid,userId,operation,requestKey,body:{reconciliationId:id.data,lineId:lineId.data,journalLineId:p.data.journalLineId}});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}const rec=await client.query<{period_from:string;period_to:string;status:string;branch_id:string|null}>("SELECT period_from::text,period_to::text,status,branch_id FROM bank_reconciliations WHERE company_id=$1 AND id=$2 AND ($3::uuid IS NULL OR branch_id IS NULL OR branch_id=$3) FOR UPDATE",[cid,id.data,req.auth!.branchId]);if(!rec.rowCount)throw Object.assign(new Error("Bank reconciliation was not found."),{httpStatus:404});if(rec.rows[0].status!=="draft")throw Object.assign(new Error("A completed reconciliation cannot be changed."),{httpStatus:409,errorCode:"RECONCILIATION_COMPLETED"});const statement=await client.query<{amount:string}>("SELECT amount::text FROM bank_reconciliation_lines WHERE company_id=$1 AND reconciliation_id=$2 AND id=$3 AND matched_journal_line_id IS NULL FOR UPDATE",[cid,id.data,lineId.data]);if(!statement.rowCount)throw Object.assign(new Error("This statement row is missing or already matched."),{httpStatus:409,errorCode:"STATEMENT_LINE_MATCHED"});const bank=await client.query<{date:string;amount:string}>("SELECT je.effective_date::text AS date,(jl.debit-jl.credit)::text AS amount FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE jl.company_id=$1 AND jl.id=$2 AND a.code='1120' AND ($3::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$3) FOR UPDATE OF jl,je",[cid,p.data.journalLineId,rec.rows[0].branch_id]);if(!bank.rowCount)throw Object.assign(new Error("Choose a posted transaction from the bank ledger."),{httpStatus:400,errorCode:"BANK_LINE_INVALID"});if(bank.rows[0].date<rec.rows[0].period_from||bank.rows[0].date>rec.rows[0].period_to||cents(Number(bank.rows[0].amount))!==cents(Number(statement.rows[0].amount)))throw Object.assign(new Error("The bank transaction must be in this period and have the same signed amount as the statement row."),{httpStatus:409,errorCode:"BANK_LINE_MISMATCH"});await client.query("UPDATE bank_reconciliation_lines SET matched_journal_line_id=$4,matched_by=$5,matched_at=now() WHERE company_id=$1 AND reconciliation_id=$2 AND id=$3",[cid,id.data,lineId.data,p.data.journalLineId,req.auth!.userId]);await client.query("INSERT INTO audit_logs(company_id,branch_id,actor_user_id,action,entity_type,entity_id,after_data) VALUES($1,$5,$2,'bank.reconcile.match','bank_reconciliation_line',$3,$4::jsonb)",[cid,req.auth!.userId,lineId.data,JSON.stringify({reconciliationId:id.data,journalLineId:p.data.journalLineId,amount:statement.rows[0].amount}),rec.rows[0].branch_id]);const response={success:true};await completeIdempotencyKey(client,{companyId:cid,userId,operation,requestKey,status:200,body:response});await client.query("COMMIT");return res.json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"BANK_MATCH_INVALID",message:(e as Error).message}});if((e as {code?:string}).code==="23505")return res.status(409).json({error:{code:"BANK_LINE_ALREADY_MATCHED",message:"This posted transaction has already been matched."}});return next(e);}finally{client.release();}});
const bankUnmatchSchema=z.object({reason:z.string().trim().min(5).max(500)});
app.post("/api/accounting/bank-reconciliations/:id/lines/:lineId/unmatch",requireAuth,requirePermission("bank.reconcile.match"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id),lineId=z.string().uuid().safeParse(req.params.lineId),p=bankUnmatchSchema.safeParse(req.body);if(!id.success||!lineId.success)return res.status(404).json({error:{code:"BANK_RECONCILIATION_NOT_FOUND",message:"Bank reconciliation line was not found."}});if(!p.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Enter a reason of at least five characters to remove a match."}});const companyId=req.auth!.companyId,userId=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation=`accounting.bank_reconciliation.unmatch:${id.data}:${lineId.data}`,client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId,userId,operation,requestKey,body:{reconciliationId:id.data,lineId:lineId.data,reason:p.data.reason}});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}const status=await client.query<{status:string;branch_id:string|null}>("SELECT status,branch_id FROM bank_reconciliations WHERE company_id=$1 AND id=$2 AND ($3::uuid IS NULL OR branch_id IS NULL OR branch_id=$3) FOR UPDATE",[req.auth!.companyId,id.data,req.auth!.branchId]);if(!status.rowCount)throw Object.assign(new Error("Bank reconciliation was not found."),{httpStatus:404});if(status.rows[0].status!=="draft")throw Object.assign(new Error("A completed reconciliation cannot be changed."),{httpStatus:409,errorCode:"RECONCILIATION_COMPLETED"});const result=await client.query("UPDATE bank_reconciliation_lines SET matched_journal_line_id=NULL,matched_by=NULL,matched_at=NULL WHERE company_id=$1 AND reconciliation_id=$2 AND id=$3 AND matched_journal_line_id IS NOT NULL RETURNING id",[req.auth!.companyId,id.data,lineId.data]);if(!result.rowCount)throw Object.assign(new Error("This statement row does not have a match."),{httpStatus:409,errorCode:"STATEMENT_LINE_UNMATCHED"});await client.query("INSERT INTO audit_logs(company_id,branch_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$6,$2,'bank.reconcile.unmatch','bank_reconciliation_line',$3,$4,jsonb_build_object('reconciliationId',$5::text))",[req.auth!.companyId,req.auth!.userId,lineId.data,p.data.reason,id.data,status.rows[0].branch_id]);const response={success:true};await completeIdempotencyKey(client,{companyId,userId,operation,requestKey,status:200,body:response});await client.query("COMMIT");return res.json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"BANK_UNMATCH_INVALID",message:(e as Error).message}});return next(e);}finally{client.release();}});
app.post("/api/accounting/bank-reconciliations/:id/complete",requireAuth,requirePermission("bank.reconcile.complete"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id);if(!id.success)return res.status(404).json({error:{code:"BANK_RECONCILIATION_NOT_FOUND",message:"Bank reconciliation was not found."}});const requestKey=(req.get("Idempotency-Key")??"").trim(),operation="accounting.bank_reconciliation.complete:"+id.data,client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:req.auth!.companyId,userId:req.auth!.userId,operation,requestKey,body:{reconciliationId:id.data}});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`bank-book:${req.auth!.companyId}`]);const rec=await client.query<{period_from:string;period_to:string;statement_closing:string;status:string;reconciliation_number:string;branch_id:string|null}>("SELECT period_from::text,period_to::text,statement_closing::text,status,reconciliation_number,branch_id FROM bank_reconciliations WHERE company_id=$1 AND id=$2 AND ($3::uuid IS NULL OR branch_id IS NULL OR branch_id=$3) FOR UPDATE",[req.auth!.companyId,id.data,req.auth!.branchId]);if(!rec.rowCount)throw Object.assign(new Error("Bank reconciliation was not found."),{httpStatus:404});const x=rec.rows[0];if(x.status!=="draft")throw Object.assign(new Error("This reconciliation is already complete."),{httpStatus:409,errorCode:"RECONCILIATION_COMPLETED"});const unmatchedStatement=await client.query("SELECT count(*)::int AS count FROM bank_reconciliation_lines WHERE company_id=$1 AND reconciliation_id=$2 AND matched_journal_line_id IS NULL",[req.auth!.companyId,id.data]);if(unmatchedStatement.rows[0].count)throw Object.assign(new Error("Match every statement line to a posted bank transaction before completing."),{httpStatus:409,errorCode:"STATEMENT_LINES_UNMATCHED"});const [book,unmatched]=await Promise.all([client.query<{amount:string}>("SELECT COALESCE(SUM(jl.debit-jl.credit),0)::text AS amount FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE jl.company_id=$1 AND a.code='1120' AND je.effective_date<=$2::date AND ($3::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$3)",[req.auth!.companyId,x.period_to,x.branch_id]),client.query<{amount:string}>("SELECT COALESCE(SUM(jl.debit-jl.credit),0)::text AS amount FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE jl.company_id=$1 AND a.code='1120' AND je.source_type<>'bank_opening_balance' AND je.effective_date BETWEEN $2::date AND $3::date AND ($4::uuid IS NULL OR je.branch_id IS NULL OR je.branch_id=$4) AND NOT EXISTS(SELECT 1 FROM bank_reconciliation_lines l WHERE l.company_id=jl.company_id AND l.matched_journal_line_id=jl.id)",[req.auth!.companyId,x.period_from,x.period_to,x.branch_id])]),bookBalance=cents(Number(book.rows[0].amount)),outstanding=cents(Number(unmatched.rows[0].amount)),adjusted=cents(bookBalance-outstanding),statementClosing=cents(Number(x.statement_closing));if(Math.abs(adjusted-statementClosing)>.01)throw Object.assign(new Error(`Adjusted book balance ₹${adjusted.toFixed(2)} does not match statement closing ₹${statementClosing.toFixed(2)}. Check the opening balance and outstanding transactions.`),{httpStatus:409,errorCode:"BANK_BALANCE_MISMATCH"});await client.query("UPDATE bank_reconciliations SET status='reconciled',completed_by=$3,completed_at=now() WHERE company_id=$1 AND id=$2 AND ($4::uuid IS NULL OR branch_id IS NULL OR branch_id=$4)",[req.auth!.companyId,id.data,req.auth!.userId,x.branch_id]);await client.query("INSERT INTO audit_logs(company_id,branch_id,actor_user_id,action,entity_type,entity_id,after_data) VALUES($1,$5,$2,'bank.reconcile.complete','bank_reconciliation',$3,$4::jsonb)",[req.auth!.companyId,req.auth!.userId,id.data,JSON.stringify({reconciliationNumber:x.reconciliation_number,periodFrom:x.period_from,periodTo:x.period_to,bookBalance,outstandingBookAmount:outstanding,adjustedBookBalance:adjusted,statementClosing,matchedStatementLines:true}),x.branch_id]);const response={success:true,adjustedBookBalance:adjusted,statementClosing};await completeIdempotencyKey(client,{companyId:req.auth!.companyId,userId:req.auth!.userId,operation,requestKey,status:200,body:response});await client.query("COMMIT");return res.json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"BANK_RECONCILIATION_INVALID",message:(e as Error).message}});return next(e);}finally{client.release();}});

const periodCloseSchema=z.object({periodStart:z.string().date(),reason:z.string().trim().min(10).max(500)});
const financialYearSchema=z.object({name:z.string().trim().min(4).max(40),startsOn:z.string().date(),endsOn:z.string().date()}).superRefine((x,ctx)=>{if(x.endsOn<=x.startsOn)ctx.addIssue({code:"custom",path:["endsOn"],message:"End date must be after start date."});});
app.get("/api/accounting/financial-years",requireAuth,requirePermission("accounting.financial-years.view"),async(req,res,next)=>{try{const q=await pool.query(`SELECT fy.id,fy.name,fy.starts_on::text AS \"startsOn\",fy.ends_on::text AS \"endsOn\",fy.status,COUNT(c.id)::int AS \"closedMonths\",yc.close_number AS \"closeNumber\",yc.net_profit AS \"netProfit\",yc.closed_at AS \"closedAt\",yc.reason AS \"closeReason\",os.id IS NOT NULL AS \"hasOpeningSnapshot\",os.captured_at AS \"openingSnapshotAt\" FROM financial_years fy LEFT JOIN accounting_period_closures c ON c.company_id=fy.company_id AND c.period_start>=fy.starts_on AND c.period_end<=fy.ends_on LEFT JOIN financial_year_closures yc ON yc.company_id=fy.company_id AND yc.financial_year_id=fy.id LEFT JOIN financial_year_opening_snapshots os ON os.company_id=fy.company_id AND os.financial_year_id=fy.id WHERE fy.company_id=$1 GROUP BY fy.id,yc.close_number,yc.net_profit,yc.closed_at,yc.reason,os.id ORDER BY fy.starts_on DESC`,[req.auth!.companyId]);return res.json({years:q.rows});}catch(e){return next(e);}});
app.get("/api/accounting/financial-years/:id/opening-balances",requireAuth,requirePermission("accounting.financial-years.view"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id);if(!id.success)return res.status(404).json({error:{code:"FINANCIAL_YEAR_NOT_FOUND",message:"Financial year was not found."}});try{const snapshot=await pool.query(`SELECT s.id,s.reason,s.source_close_id AS \"sourceCloseId\",s.captured_at AS \"capturedAt\",u.full_name AS \"capturedBy\",fy.name AS \"financialYear\",fy.starts_on::text AS \"startsOn\" FROM financial_year_opening_snapshots s JOIN financial_years fy ON fy.company_id=s.company_id AND fy.id=s.financial_year_id LEFT JOIN users u ON u.company_id=s.company_id AND u.id=s.captured_by WHERE s.company_id=$1 AND s.financial_year_id=$2`,[req.auth!.companyId,id.data]);if(!snapshot.rowCount)return res.json({snapshot:null,lines:[],totalDebit:0,totalCredit:0});const lines=await pool.query(`SELECT account_code AS code,account_name AS name,account_type AS \"accountType\",opening_debit AS debit,opening_credit AS credit FROM financial_year_opening_snapshot_lines WHERE company_id=$1 AND snapshot_id=$2 ORDER BY account_code`,[req.auth!.companyId,snapshot.rows[0].id]);const rows=lines.rows.map(r=>({...r,debit:Number(r.debit),credit:Number(r.credit)}));return res.json({snapshot:snapshot.rows[0],lines:rows,totalDebit:rows.reduce((sum,r)=>sum+r.debit,0),totalCredit:rows.reduce((sum,r)=>sum+r.credit,0)});}catch(e){return next(e);}});
app.post("/api/accounting/financial-years",requireAuth,requirePermission("accounting.financial-years.configure"),async(req,res,next)=>{const parsed=financialYearSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Enter a year name and a valid start and end date."}});const x=parsed.data,cid=req.auth!.companyId,actor=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation="accounting.financial_year.create",client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,body:x});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}const saved=await client.query<{id:string}>("INSERT INTO financial_years(company_id,name,starts_on,ends_on) VALUES($1,$2,$3,$4) RETURNING id",[cid,x.name,x.startsOn,x.endsOn]);await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,after_data) VALUES($1,$2,'accounting.financial_year.create','financial_year',$3,$4::jsonb)",[cid,actor,saved.rows[0].id,JSON.stringify(x)]);const response={id:saved.rows[0].id,...x,status:"open"};await completeIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,status:201,body:response});await client.query("COMMIT");return res.status(201).json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);if((e as {code?:string}).code==="23P01")return res.status(409).json({error:{code:"FINANCIAL_YEAR_OVERLAP",message:"This date range overlaps an existing financial year."}});if((e as {code?:string}).code==="23505")return res.status(409).json({error:{code:"FINANCIAL_YEAR_NAME_EXISTS",message:"A financial year with this name already exists."}});return next(e);}finally{client.release();}});
const openingSnapshotSchema=z.object({reason:z.string().trim().min(10).max(500)});
app.post("/api/accounting/financial-years/:id/opening-balances",requireAuth,requirePermission("accounting.financial-years.configure"),async(req,res,next)=>{const id=z.string().uuid().safeParse(req.params.id),parsed=openingSnapshotSchema.safeParse(req.body);if(!id.success)return res.status(404).json({error:{code:"FINANCIAL_YEAR_NOT_FOUND",message:"Financial year was not found."}});if(!parsed.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Enter a reason of at least ten characters for capturing the opening balances."}});const cid=req.auth!.companyId,actor=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation="accounting.financial_year.opening_snapshot:"+id.data,client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,body:parsed.data});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`accounting-period:${cid}`]);const year=await client.query<{starts_on:string;status:string}>("SELECT starts_on::text,status FROM financial_years WHERE company_id=$1 AND id=$2 FOR UPDATE",[cid,id.data]);if(!year.rowCount)throw Object.assign(new Error("Financial year was not found."),{httpStatus:404,errorCode:"FINANCIAL_YEAR_NOT_FOUND"});if(year.rows[0].status==="closing")throw Object.assign(new Error("This financial year is being closed."),{httpStatus:409,errorCode:"FINANCIAL_YEAR_CLOSED"});const existing=await client.query("SELECT id FROM financial_year_opening_snapshots WHERE company_id=$1 AND financial_year_id=$2",[cid,id.data]);if(existing.rowCount)throw Object.assign(new Error("Opening balances have already been captured for this financial year."),{httpStatus:409,errorCode:"OPENING_SNAPSHOT_EXISTS"});const prior=await client.query<{status:string;close_id:string|null}>("SELECT fy.status,yc.id AS close_id FROM financial_years fy LEFT JOIN financial_year_closures yc ON yc.company_id=fy.company_id AND yc.financial_year_id=fy.id WHERE fy.company_id=$1 AND fy.ends_on<$2::date ORDER BY fy.ends_on DESC LIMIT 1 FOR UPDATE OF fy",[cid,year.rows[0].starts_on]);if(prior.rowCount&&prior.rows[0].status!=="closed")throw Object.assign(new Error("Close the preceding financial year before capturing these opening balances."),{httpStatus:409,errorCode:"PREVIOUS_FINANCIAL_YEAR_OPEN"});if(prior.rowCount&&!prior.rows[0].close_id)throw Object.assign(new Error("The preceding financial year must have an audited year-end close before balances can be captured."),{httpStatus:409,errorCode:"PREVIOUS_FINANCIAL_YEAR_CLOSE_REQUIRED"});const snapshot=await captureFinancialYearOpeningSnapshot(client,{companyId:cid,financialYearId:id.data,actorId:actor,reason:parsed.data.reason});await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'accounting.financial_year.opening_snapshot','financial_year_opening_snapshot',$3,$4,$5::jsonb)",[cid,actor,snapshot.id,parsed.data.reason,JSON.stringify({...snapshot,financialYearId:id.data})]);await completeIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,status:201,body:snapshot});await client.query("COMMIT");return res.status(201).json(snapshot);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"OPENING_SNAPSHOT_INVALID",message:(e as Error).message}});if((e as {code?:string}).code==="23505")return res.status(409).json({error:{code:"OPENING_SNAPSHOT_EXISTS",message:"Opening balances have already been captured for this financial year."}});return next(e);}finally{client.release();}});
const financialYearCloseSchema=z.object({financialYearId:z.string().uuid(),reason:z.string().trim().min(10).max(500)});
app.post("/api/accounting/financial-years/close",requireAuth,requirePermission("accounting.financial-years.close"),async(req,res,next)=>{
 const parsed=financialYearCloseSchema.safeParse(req.body);
 if(!parsed.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Choose a financial year and enter a reason of at least ten characters."}});
 const{financialYearId,reason}=parsed.data,cid=req.auth!.companyId,actor=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation="accounting.financial_year.close:"+financialYearId,client=await pool.connect();
 try{
  await client.query("BEGIN");
  const claim=await claimIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,body:parsed.data});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}
  await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`accounting-period:${cid}`]);
  const fy=await client.query<{name:string;starts_on:string;ends_on:string;status:string;today:string}>("SELECT fy.name,fy.starts_on::text,fy.ends_on::text,fy.status,timezone(c.timezone,now())::date::text AS today FROM financial_years fy JOIN companies c ON c.id=fy.company_id WHERE fy.company_id=$1 AND fy.id=$2 FOR UPDATE OF fy",[cid,financialYearId]);
  if(!fy.rowCount)throw Object.assign(new Error("Financial year was not found."),{httpStatus:404,errorCode:"FINANCIAL_YEAR_NOT_FOUND"});
  const year=fy.rows[0];
  if(year.status!=="open")throw Object.assign(new Error("This financial year is already closed or being closed."),{httpStatus:409,errorCode:"FINANCIAL_YEAR_CLOSED"});
  if(year.ends_on>=year.today)throw Object.assign(new Error("Close a financial year only after its final date."),{httpStatus:409,errorCode:"FINANCIAL_YEAR_NOT_COMPLETE"});
  const next=await client.query<{id:string;starts_on:string;status:string}>("SELECT id,starts_on::text,status FROM financial_years WHERE company_id=$1 AND starts_on=$2::date+1 FOR UPDATE",[cid,year.ends_on]);
  if(!next.rowCount||next.rows[0].status!=="open")throw Object.assign(new Error("Create the next consecutive open financial year before closing this year."),{httpStatus:409,errorCode:"NEXT_FINANCIAL_YEAR_REQUIRED"});
  const monthCheck=await client.query<{expected:number;closed:number}>(`WITH months AS (SELECT d::date AS starts FROM generate_series(date_trunc('month',$2::date),date_trunc('month',$3::date),interval '1 month') d) SELECT count(*)::int AS expected,count(c.id)::int AS closed FROM months m LEFT JOIN accounting_period_closures c ON c.company_id=$1 AND c.period_start=m.starts AND c.period_end=(m.starts+interval '1 month - 1 day')::date WHERE m.starts>=$2::date AND (m.starts+interval '1 month - 1 day')::date<=$3::date`,[cid,year.starts_on,year.ends_on]);
  if(monthCheck.rows[0].expected!==12||monthCheck.rows[0].closed!==12)throw Object.assign(new Error("Close all twelve accounting months in this financial year before year-end close."),{httpStatus:409,errorCode:"FINANCIAL_YEAR_MONTHS_OPEN"});
  const pnl=await client.query<{code:string;account_type:string;normal_balance:string}>(`SELECT a.code,a.account_type,(CASE WHEN a.account_type='income' THEN SUM(jl.credit)-SUM(jl.debit) ELSE SUM(jl.debit)-SUM(jl.credit) END)::numeric(14,2)::text AS normal_balance FROM journal_entries je JOIN journal_entry_lines jl ON jl.company_id=je.company_id AND jl.journal_entry_id=je.id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE je.company_id=$1 AND je.financial_year_id=$2 AND je.source_type<>'financial_year_close' AND a.account_type IN ('income','expense') GROUP BY a.code,a.account_type ORDER BY a.code`,[cid,financialYearId]);
  let profit=0;
  const lines:Array<{accountCode:string;description:string;debit:number;credit:number}>=[];
  for(const row of pnl.rows){
   const normalBalance=Number(row.normal_balance);
   profit+=row.account_type==="income"?normalBalance:-normalBalance;
   if(Math.abs(normalBalance)<0.005)continue;
   const debit=row.account_type==="income"?normalBalance>0:normalBalance<0,amount=Math.abs(normalBalance);
   lines.push({accountCode:row.code,description:`Year-end close ${year.name}`,debit:debit?amount:0,credit:debit?0:amount});
  }
  profit=cents(profit);
  if(profit>0)lines.push({accountCode:"3100",description:`Retained profit ${year.name}`,debit:0,credit:profit});
  else if(profit<0)lines.push({accountCode:"3100",description:`Retained loss ${year.name}`,debit:Math.abs(profit),credit:0});
  let closingEntryId:string|null=null;
  if(lines.length)closingEntryId=await writeJournal(client,{companyId:cid,actorId:actor,sourceType:"financial_year_close",sourceId:financialYearId,description:`Financial year close ${year.name}`,effectiveDate:next.rows[0].starts_on,lines});
  const closeNumber=await nextDocumentNumber(client,cid,"financial_year_close");
  const close=await client.query<{id:string}>("INSERT INTO financial_year_closures(company_id,financial_year_id,next_financial_year_id,close_number,closing_entry_id,net_profit,reason,closed_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id",[cid,financialYearId,next.rows[0].id,closeNumber,closingEntryId,profit,reason,actor]);
  const openingSnapshot=await captureFinancialYearOpeningSnapshot(client,{companyId:cid,financialYearId:next.rows[0].id,actorId:actor,reason:`Opening balances carried forward from ${closeNumber}: ${reason}`,sourceCloseId:close.rows[0].id});
  await client.query("UPDATE financial_years SET status='closed' WHERE company_id=$1 AND id=$2",[cid,financialYearId]);
  await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'accounting.financial_year.close','financial_year',$3,$4,$5::jsonb)",[cid,actor,financialYearId,reason,JSON.stringify({closeNumber,nextFinancialYearId:next.rows[0].id,closingEntryId,netProfit:profit,closedMonths:12,openingSnapshot})]);
  const response={success:true,closeNumber,financialYearId,closingEntryId,netProfit:profit,openingSnapshot};
  await completeIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,status:201,body:response});
  await client.query("COMMIT");
  return res.status(201).json(response);
 }catch(e){
  await client.query("ROLLBACK").catch(()=>undefined);
  const status=(e as{httpStatus?:number}).httpStatus;
  if(status)return res.status(status).json({error:{code:(e as{errorCode?:string}).errorCode??"FINANCIAL_YEAR_CLOSE_REJECTED",message:(e as Error).message}});
  return next(e);
 }finally{client.release();}
});
app.get("/api/accounting/period-closures",requireAuth,requirePermission("accounting.period.close.view"),async(req,res,next)=>{try{const q=await pool.query(`SELECT c.id,c.close_number AS \"closeNumber\",c.period_start::text AS \"periodStart\",c.period_end::text AS \"periodEnd\",c.reason,c.closed_at AS \"closedAt\",u.full_name AS \"closedBy\" FROM accounting_period_closures c JOIN users u ON u.company_id=c.company_id AND u.id=c.closed_by WHERE c.company_id=$1 ORDER BY c.period_start DESC LIMIT 60`,[req.auth!.companyId]);return res.json({closures:q.rows});}catch(e){return next(e);}});
app.post("/api/accounting/period-closures",requireAuth,requirePermission("accounting.period.close"),async(req,res,next)=>{const parsed=periodCloseSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:{code:"VALIDATION_ERROR",message:"Select the first date of a month and enter a close reason of at least ten characters."}});const x=parsed.data,start=new Date(`${x.periodStart}T00:00:00.000Z`);if(start.getUTCDate()!==1)return res.status(400).json({error:{code:"INVALID_PERIOD_START",message:"Choose the first day of a calendar month."}});const periodEnd=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).toISOString().slice(0,10),cid=req.auth!.companyId,actor=req.auth!.userId,requestKey=(req.get("Idempotency-Key")??"").trim(),operation="accounting.period.close",client=await pool.connect();try{await client.query("BEGIN");const claim=await claimIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,body:x});if(claim.replay){await client.query("COMMIT");return res.status(claim.status).json(claim.body);}await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[`accounting-period:${cid}`]);const dates=await client.query<{today:string}>("SELECT timezone(c.timezone,now())::date::text AS today FROM companies c WHERE c.id=$1",[cid]);if(periodEnd>=dates.rows[0].today)throw Object.assign(new Error("Close a completed month only; the selected month has not ended yet."),{httpStatus:409,errorCode:"PERIOD_NOT_COMPLETE"});const existing=await client.query("SELECT id FROM accounting_period_closures WHERE company_id=$1 AND period_start=$2::date",[cid,x.periodStart]);if(existing.rowCount)throw Object.assign(new Error("This accounting month is already closed."),{httpStatus:409,errorCode:"PERIOD_ALREADY_CLOSED"});const totals=await client.query<{debit:string;credit:string}>("SELECT COALESCE(SUM(jl.debit),0)::text debit,COALESCE(SUM(jl.credit),0)::text credit FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id WHERE jl.company_id=$1 AND je.effective_date BETWEEN $2::date AND $3::date",[cid,x.periodStart,periodEnd]);if(Math.abs(Number(totals.rows[0].debit)-Number(totals.rows[0].credit))>.01)throw Object.assign(new Error("The month's posted journal debits and credits do not balance."),{httpStatus:409,errorCode:"PERIOD_TRIAL_BALANCE_MISMATCH"});const pendingCash=await client.query("SELECT id FROM cash_closings WHERE company_id=$1 AND status='pending' AND closing_date BETWEEN $2::date AND $3::date LIMIT 1",[cid,x.periodStart,periodEnd]);if(pendingCash.rowCount)throw Object.assign(new Error("Approve every cash variance in this month before closing it."),{httpStatus:409,errorCode:"PERIOD_CASH_VARIANCE_PENDING"});const missingCash=await client.query("SELECT je.effective_date::text AS date FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id LEFT JOIN cash_closings cc ON cc.company_id=jl.company_id AND cc.closing_date=je.effective_date AND cc.status='approved' AND ((je.branch_id IS NULL AND cc.branch_id IS NULL) OR (je.branch_id IS NOT NULL AND cc.branch_id=je.branch_id)) WHERE jl.company_id=$1 AND a.code='1110' AND je.effective_date BETWEEN $2::date AND $3::date AND cc.id IS NULL LIMIT 1",[cid,x.periodStart,periodEnd]);if(missingCash.rowCount)throw Object.assign(new Error(`Record and approve the daily cash close for ${missingCash.rows[0].date} before closing the month.`),{httpStatus:409,errorCode:"PERIOD_CASH_CLOSE_MISSING"});const draftBank=await client.query("SELECT id FROM bank_reconciliations WHERE company_id=$1 AND status='draft' AND period_from<=$3::date AND period_to>=$2::date LIMIT 1",[cid,x.periodStart,periodEnd]);if(draftBank.rowCount)throw Object.assign(new Error("Complete or resolve every bank reconciliation covering this month before closing it."),{httpStatus:409,errorCode:"PERIOD_BANK_RECONCILIATION_PENDING"});const bankActivity=await client.query("SELECT EXISTS(SELECT 1 FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id WHERE jl.company_id=$1 AND a.code='1120' AND je.effective_date BETWEEN $2::date AND $3::date) AS exists",[cid,x.periodStart,periodEnd]);const unreconciledBankBranch=await client.query("SELECT je.branch_id FROM journal_entry_lines jl JOIN journal_entries je ON je.company_id=jl.company_id AND je.id=jl.journal_entry_id JOIN accounts a ON a.company_id=jl.company_id AND a.id=jl.account_id LEFT JOIN bank_reconciliations r ON r.company_id=je.company_id AND r.status='reconciled' AND r.period_from<=$2::date AND r.period_to>=$3::date AND (r.branch_id IS NULL OR r.branch_id=je.branch_id) WHERE jl.company_id=$1 AND a.code='1120' AND je.effective_date BETWEEN $2::date AND $3::date GROUP BY je.branch_id HAVING count(r.id)=0 LIMIT 1",[cid,x.periodStart,periodEnd]);if(unreconciledBankBranch.rowCount)throw Object.assign(new Error("Reconcile bank activity for every active branch for the full month before closing it."),{httpStatus:409,errorCode:"PERIOD_BANK_RECONCILIATION_REQUIRED"});const number=await nextDocumentNumber(client,cid,"accounting_period_close"),saved=await client.query<{id:string}>("INSERT INTO accounting_period_closures(company_id,close_number,period_start,period_end,reason,closed_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING id",[cid,number,x.periodStart,periodEnd,x.reason,actor]);await client.query("INSERT INTO audit_logs(company_id,actor_user_id,action,entity_type,entity_id,reason,after_data) VALUES($1,$2,'accounting.period.close','accounting_period_closure',$3,$4,$5::jsonb)",[cid,actor,saved.rows[0].id,x.reason,JSON.stringify({closeNumber:number,periodStart:x.periodStart,periodEnd,journalDebits:Number(totals.rows[0].debit),journalCredits:Number(totals.rows[0].credit),cashChecksPassed:true,bankCheckRequired:bankActivity.rows[0].exists})]);const response={id:saved.rows[0].id,closeNumber:number,periodStart:x.periodStart,periodEnd};await completeIdempotencyKey(client,{companyId:cid,userId:actor,operation,requestKey,status:201,body:response});await client.query("COMMIT");return res.status(201).json(response);}catch(e){await client.query("ROLLBACK").catch(()=>undefined);const status=(e as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(e as {errorCode?:string}).errorCode??"PERIOD_CLOSE_REJECTED",message:(e as Error).message}});if((e as {code?:string}).code==="23505")return res.status(409).json({error:{code:"PERIOD_ALREADY_CLOSED",message:"This accounting month is already closed."}});return next(e);}finally{client.release();}});

app.get("/api/sales/orders/:id",requireAuth,requirePermission("sales.view"),async(req,res,next)=>{
 const id=z.string().uuid().safeParse(req.params.id);
 if(!id.success)return res.status(404).json({error:{code:"SALES_ORDER_NOT_FOUND",message:"Sales order was not found."}});
 try{
  const order=await pool.query(`SELECT o.id,o.order_number AS \"orderNumber\",o.order_date::text AS \"orderDate\",o.status,o.subtotal,o.tax_total AS \"taxTotal\",o.total,c.id AS \"customerId\",c.name AS \"customerName\",c.code AS \"customerCode\",b.id AS \"brokerId\",b.name AS \"brokerName\",u.full_name AS \"createdBy\",o.created_at AS \"createdAt\" FROM sales_orders o JOIN business_partners c ON c.company_id=o.company_id AND c.id=o.customer_id LEFT JOIN business_partners b ON b.company_id=o.company_id AND b.id=o.broker_id JOIN users u ON u.company_id=o.company_id AND u.id=o.created_by WHERE o.company_id=$1 AND o.id=$2 AND ($3::uuid IS NULL OR o.branch_id IS NULL OR o.branch_id=$3)`,[req.auth!.companyId,id.data,req.auth!.branchId]);
  if(!order.rowCount)return res.status(404).json({error:{code:"SALES_ORDER_NOT_FOUND",message:"Sales order was not found in the active branch."}});
  const [lines,invoices]=await Promise.all([
   pool.query(`SELECT l.id,l.line_number AS \"lineNumber\",p.id AS \"productId\",p.code AS \"productCode\",p.name AS \"productName\",l.quality,l.quantity AS \"baseQuantity\",p.unit AS \"baseUnit\",l.entered_quantity AS \"enteredQuantity\",l.entered_unit_code AS \"enteredUnitCode\",COALESCE(pu.label,l.entered_unit_code) AS \"enteredUnitLabel\",l.conversion_to_base AS \"conversionToBase\",l.unit_rate AS \"unitRate\",l.tax_rate AS \"taxRate\",l.line_subtotal AS subtotal,l.tax_amount AS tax,l.line_total AS total FROM sales_order_lines l JOIN products p ON p.company_id=l.company_id AND p.id=l.product_id LEFT JOIN product_units pu ON pu.company_id=l.company_id AND pu.product_id=l.product_id AND pu.code=l.entered_unit_code WHERE l.company_id=$1 AND l.order_id=$2 ORDER BY l.line_number`,[req.auth!.companyId,id.data]),
   pool.query(`SELECT i.id,i.invoice_number AS \"invoiceNumber\",i.invoice_date::text AS \"invoiceDate\",i.status,i.subtotal,i.tax_total AS \"taxTotal\",i.total,COALESCE((SELECT SUM(r.amount) FROM customer_receipts r WHERE r.company_id=i.company_id AND r.invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM customer_receipt_allocations a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0) AS \"amountPaid\",COALESCE((SELECT SUM(sr.total) FROM sales_returns sr WHERE sr.company_id=i.company_id AND sr.invoice_id=i.id),0) AS \"returnedAmount\",CASE WHEN i.status='reversed' THEN 0 ELSE i.total-COALESCE((SELECT SUM(r.amount) FROM customer_receipts r WHERE r.company_id=i.company_id AND r.invoice_id=i.id),0)-COALESCE((SELECT SUM(a.amount) FROM customer_receipt_allocations a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0)-COALESCE((SELECT SUM(sr.total) FROM sales_returns sr WHERE sr.company_id=i.company_id AND sr.invoice_id=i.id),0)-COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a JOIN sales_returns sr ON sr.company_id=a.company_id AND sr.id=a.sales_return_id WHERE a.company_id=i.company_id AND sr.invoice_id=i.id),0)+COALESCE((SELECT SUM(f.amount) FROM customer_refunds f JOIN sales_returns sr ON sr.company_id=f.company_id AND sr.id=f.sales_return_id WHERE f.company_id=i.company_id AND sr.invoice_id=i.id),0) END AS outstanding FROM sales_invoices i WHERE i.company_id=$1 AND i.order_id=$2 AND ($3::uuid IS NULL OR i.branch_id IS NULL OR i.branch_id=$3) ORDER BY i.invoice_date,i.invoice_number`,[req.auth!.companyId,id.data,req.auth!.branchId])
  ]);
  return res.json({order:order.rows[0],lines:lines.rows,invoices:invoices.rows});
 }catch(error){return next(error);}
});

const branchTradingReportFilterSchema=z.object({from:z.string().date().optional(),to:z.string().date().optional()});
app.get("/api/reports/branches/trading",requireAuth,requirePermission("accounting.view"),async(req,res,next)=>{
 const parsed=branchTradingReportFilterSchema.safeParse(req.query);
 if(!parsed.success||(parsed.data.from&&parsed.data.to&&parsed.data.from>parsed.data.to))return res.status(400).json({error:{code:"INVALID_REPORT_FILTER",message:"Choose a valid start and end date."}});
 try{
  const owner=await pool.query<{allowed:boolean}>(`SELECT EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.company_id=ur.company_id AND r.id=ur.role_id WHERE ur.company_id=$1 AND ur.user_id=$2 AND r.code='owner') AS allowed`,[req.auth!.companyId,req.auth!.userId]);
  if(!owner.rows[0]?.allowed)return res.status(403).json({error:{code:"OWNER_ACCESS_REQUIRED",message:"Only an owner can compare all company branches."}});
  const q=await pool.query(`WITH dimensions AS (
   SELECT id AS branch_id,code AS branch_code,name AS branch_name FROM branches WHERE company_id=$1
   UNION ALL SELECT NULL::uuid,'SHARED','Shared / unassigned'
  ), sales_invoice_amounts AS (
   SELECT i.company_id,i.id,i.branch_id,i.status,i.total,
    COALESCE((SELECT SUM(r.amount) FROM customer_receipts r WHERE r.company_id=i.company_id AND r.invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM customer_receipt_allocations a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0) paid,
    COALESCE((SELECT SUM(sr.total) FROM sales_returns sr WHERE sr.company_id=i.company_id AND sr.invoice_id=i.id),0) returned,
    COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a WHERE a.company_id=i.company_id AND a.target_invoice_id=i.id),0) credits_applied,
    COALESCE((SELECT SUM(a.amount) FROM customer_credit_applications a JOIN sales_returns sr ON sr.company_id=a.company_id AND sr.id=a.sales_return_id WHERE a.company_id=i.company_id AND sr.invoice_id=i.id),0) source_credit_applied,
    COALESCE((SELECT SUM(f.amount) FROM customer_refunds f JOIN sales_returns sr ON sr.company_id=f.company_id AND sr.id=f.sales_return_id WHERE f.company_id=i.company_id AND sr.invoice_id=i.id),0) refunded
   FROM sales_invoices i WHERE i.company_id=$1 AND ($2::date IS NULL OR i.invoice_date >= $2::date) AND ($3::date IS NULL OR i.invoice_date <= $3::date)
  ), sales AS (
   SELECT branch_id,COUNT(*) FILTER(WHERE status='posted')::int invoice_count,
    COALESCE(SUM(CASE WHEN status='posted' THEN total ELSE 0 END),0)::numeric(14,2) invoiced,
    COALESCE(SUM(paid),0)::numeric(14,2) collected,COALESCE(SUM(returned),0)::numeric(14,2) returned,
    COALESCE(SUM(CASE WHEN status='reversed' THEN 0 ELSE total-paid-returned-credits_applied+source_credit_applied+refunded END),0)::numeric(14,2) receivable
   FROM sales_invoice_amounts GROUP BY branch_id
  ), purchase_bill_amounts AS (
   SELECT b.company_id,b.id,b.branch_id,b.total,
    COALESCE((SELECT SUM(p.amount) FROM supplier_payments p WHERE p.company_id=b.company_id AND p.bill_id=b.id),0) paid,
    COALESCE((SELECT SUM(a.amount) FROM purchase_return_allocations a WHERE a.company_id=b.company_id AND a.bill_id=b.id),0) credits_applied,
    COALESCE((SELECT SUM(r.total) FROM purchase_returns r WHERE r.company_id=b.company_id AND r.bill_id=b.id),0) returned
   FROM purchase_bills b WHERE b.company_id=$1 AND ($2::date IS NULL OR b.bill_date >= $2::date) AND ($3::date IS NULL OR b.bill_date <= $3::date)
  ), purchases AS (
   SELECT branch_id,COUNT(*)::int bill_count,COALESCE(SUM(total),0)::numeric(14,2) billed,
    COALESCE(SUM(paid),0)::numeric(14,2) paid,COALESCE(SUM(credits_applied),0)::numeric(14,2) credits,
    COALESCE(SUM(returned),0)::numeric(14,2) returned,COALESCE(SUM(GREATEST(total-paid-credits_applied,0)),0)::numeric(14,2) payable
   FROM purchase_bill_amounts GROUP BY branch_id
  )
  SELECT d.branch_id AS \"branchId\",d.branch_code AS \"branchCode\",d.branch_name AS \"branchName\",
   COALESCE(s.invoice_count,0) AS \"invoiceCount\",COALESCE(s.invoiced,0) AS invoiced,COALESCE(s.collected,0) AS collected,COALESCE(s.returned,0) AS \"salesReturns\",COALESCE(s.receivable,0) AS receivable,
   COALESCE(p.bill_count,0) AS \"billCount\",COALESCE(p.billed,0) AS billed,COALESCE(p.paid,0) AS \"supplierPaid\",COALESCE(p.credits,0) AS \"supplierCredits\",COALESCE(p.returned,0) AS \"purchaseReturns\",COALESCE(p.payable,0) AS payable
  FROM dimensions d LEFT JOIN sales s ON s.branch_id IS NOT DISTINCT FROM d.branch_id LEFT JOIN purchases p ON p.branch_id IS NOT DISTINCT FROM d.branch_id
  ORDER BY (d.branch_id IS NULL),lower(d.branch_name)`,[req.auth!.companyId,parsed.data.from??null,parsed.data.to??null]);
  const totals=q.rows.reduce((a,r)=>({invoiced:a.invoiced+Number(r.invoiced),collected:a.collected+Number(r.collected),salesReturns:a.salesReturns+Number(r.salesReturns),receivable:a.receivable+Number(r.receivable),billed:a.billed+Number(r.billed),supplierPaid:a.supplierPaid+Number(r.supplierPaid),supplierCredits:a.supplierCredits+Number(r.supplierCredits),purchaseReturns:a.purchaseReturns+Number(r.purchaseReturns),payable:a.payable+Number(r.payable)}),{invoiced:0,collected:0,salesReturns:0,receivable:0,billed:0,supplierPaid:0,supplierCredits:0,purchaseReturns:0,payable:0});
  return res.json({branches:q.rows,totals,from:parsed.data.from??null,to:parsed.data.to??null,sharedBranchIncluded:true});
 }catch(error){return next(error);}
});

app.use((error: unknown, req: Request, res: Response, _next: NextFunction) => {
  console.error("Unhandled API error", { requestId: res.locals.requestId, method: req.method, path: req.path }, error);
  const status=(error as {httpStatus?:number}).httpStatus;if(status)return res.status(status).json({error:{code:(error as {errorCode?:string}).errorCode??"REQUEST_REJECTED",message:(error as Error).message}});
  const code=(error as {code?:string}).code;
  const databaseError = publicDatabaseError(code);
  if (databaseError) return res.status(databaseError.status).json({ error: { code: databaseError.code, message: databaseError.message } });
  const internal = internalErrorResponse(String(res.locals.requestId ?? randomUUID()));
  res.status(internal.status).json(internal.body);
});

